      const same = (((await dc(env, '/channels/' + c.id + '/messages?limit=100').catch(() => [])) || [])).filter((x) => x.author && x.author.id === src.author.id && BigInt(x.id) < BigInt(m.id)).sort(byId).slice(0, 6);
      if (same.length) mine = same;
