const DIFF_NAME = { 1: 'LFR', 2: 'LFR', 3: 'Normal', 4: 'Heroic', 5: 'Mythic' };
const mss = (ms) => { const s = Math.round(ms / 1000); return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0'); };
